#endif

ratios_c.content:
#include "ratios.h"
double polynomial_ratio(double n) { return (3.0 * n * n + 7.0 * n) / (2.0 * n * n); }
double lower_degree_ratio(double n) { return (2.0 * n * n * n * n - 3.0 * n * n + 7.0) / (n * n * n * n * n); }
double exponential_ratio(int n) {
    double ratio = 1.0;
    for (int i = 0; i < n; i++) ratio *= 2.0 / 3.0;
    return ratio;
}
